/* The race, run by the arcade's own code (yt::CSeq: the player's yt::CMachine and the
 * traffic, yt::COtherGen), recompiled from `main` to C (src/phys, generated by
 * tools/recomp). It runs at the arcade's fixed 60 Hz and keeps its own course model,
 * so no collision mesh is used.
 * World units are the arcade's display units: 1 unit = 0.1 m, +y up. */
#ifndef CAR_H
#define CAR_H

#include <stdint.h>
#include <stddef.h>
#include "ghost_format.h"
#include "tire_smoke.h"

typedef struct {
  float steer;    /* -1 left .. +1 right */
  float throttle; /* 0..1 */
  float brake;    /* 0..1 */
  int shift_up, shift_down; /* edge-triggered requests */
  int analog;     /* steer is the iPad's tilt (the gyro's), not the buttons' */
  int passing;    /* arcade intrusion button's rising edge, VS only */
} car_input;

/* the traffic (yt::COtherGen): its four models, in the order of data/othercar's path tables */
enum { CAR_TRAFFIC_NZE121, CAR_TRAFFIC_KZH100G, CAR_TRAFFIC_TRUCK, CAR_TRAFFIC_RC2, CAR_TRAFFIC_MODELS };
#define CAR_TRAFFIC 12 /* at most on the road at once */
#define CAR_RIVALS 3   /* SConfigPlay's rivals in one race */
typedef struct {
  int model;      /* CAR_TRAFFIC_* */
  float body[16]; /* model matrix, like car_state.body */
} car_traffic;

/* A car scraping a wall (SInfoCarEffect, CMachine/CRivalCar::GetInfoCarEffect): how hard
 * (+0x68, 0 when clear; clCarEffectManager::update throws sparks while it is not 0), the
 * contact point (+0x6c, world) and the way they fly (+0x78) */
typedef struct {
  float spark;
  float at[3], dir[3];
  /* Raw SInfoCarEffect +0x84 and +0x30, sampled per 60 Hz car_update.
   * Consumers must inspect each physics step, not each rendered frame. */
  unsigned char backfire_pulse;
  float backfire_vec[3];
  int backfire_type; /* (int)length % 2; -1 if non-finite/out of int range */
} car_effect;

/* The time attack as the arcade's consoles show it: CSeq::Get2DInfoRace and Get2DInfoMap,
 * the checkpoints' yt::CTimeKeeper and the race state (yt::CState). */
#define CAR_SECTIONS 8
#define CAR_TITLE_LOG 0x34 /* youTitle::_TitleRunningLog_ */
enum { CAR_RACE_RUN, CAR_RACE_TIME_UP, CAR_RACE_GOAL };
typedef struct {
  int state;         /* CAR_RACE_*: time up from the moment the time runs out (the car slows down) */
  int over;          /* the race is over: yt::CState reached Goal (8) or TimeUp (6, once the car
                      * has slowed down and stopped), where clRaceThread::race hands over to result2 */
  float countdown;   /* s of the start's countdown left: 4 at the start, the car rolling under the
                      * arcade's pilot (CMcPilot) till it is 0 and the race runs */
  float time_left;   /* s; each checkpoint extends it */
  float total;       /* s since the start; stops at the goal, and when the time is up */
  float remain;      /* m to the goal */
  int sections;      /* the course's sections: its checkpoints and the goal */
  int section;       /* the one being driven, 0..sections-1 (sections after the goal) */
  float split[CAR_SECTIONS + 1]; /* s since the start at the end of section k - 1 (split[0] = 0) */
  float extended;    /* s the checkpoint just passed gave; the consumer clears it */
  int area, next_area; /* EAreaId of the road under the car and of the next one */
  /* CSeq::GetInfoMyCarPlace: the car's place (EAreaId) and how far into it (mm), for
   * clCourseArrow::update's Hakone boards */
  int place;
  float place_at;
  float map_x, map_z, map_angle; /* where the minimap looks (display units) and its heading */
  int map_text;      /* the road's name on the map (EMapText, S2DInfoMap +0x14; 0 none) */
  int sign;          /* E2DSign over the car (SAreaData::GetSign): 0 none, 1..14 (hud.c) */
  /* CSeq junction getters. select_valid includes state 0 (no selection); 1
   * choosing, 2/3 selected. distance is raw engine mm, not clamped.
   * line_valid only when the line getter succeeds and all nine coordinates
   * are finite. Coordinates are engine output; coordinate space unverified. */
  int jct_select_valid, jct_state, jct_left_area, jct_right_area;
  float jct_distance;
  int jct_line_valid;
  float jct_line[3][3];
  /* clGoalLine's rows of lights across the road: bit k of lines set while row k is there (0 the
   * goal's, CSeq::GetInfoGoalLine, while the goal is ahead; 1 the next checkpoint's,
   * GetInfoSplitLine), between its two road-edge points line[k] (display units) */
  int lines;
  float line[2][2][3];
  /* against a rival (car_set_rival): the gap (CSeq::Get2DInfoStory, m; > 0 the player ahead)
   * and, once over, who won (CSeq::GetPlayResult) */
  float gap;
  /* CSeq::Exec CutInInfo+4: (machine odometer - race origin) in metres. */
  float story_distance;
  int story_distance_valid;
  float mileage_mm;     /* frozen SPlayResult +0xc, including TenWarp mileage mapping */
  int mileage_valid;
  int won;
  /* the rivals' boxes (clStoryConsole): S2DInfoStory's m each rival i is behind (negative: ahead)
   * and whether it is on (getInfoStoryAdvantage / getInfoStoryCharacterEnable) */
  float story_gap[3];
  unsigned char story_on[3];
  unsigned char story_gap_valid[3]; /* finite output written on this tick; independent of picture visibility */
  /* the 10-in-a-row (car_set_ten; CSeq::Get2DInfoTenFight): rivals beaten, the one on the road
   * (CTenSeq's number, 0 the first), s each beaten one took (ten_time[k] for rival k, the
   * one on the road's still running), s since the race's start, the gear its rolling start
   * asks for (0 none), m it is behind (negative: ahead), and whether its name / the start
   * gear show (CTenSeq::SwName/SwGear) */
  int ten_beaten, ten_rival;
  float ten_time[32], ten_now;
  int ten_gear;
  float ten_gap;
  int ten_sw_name, ten_sw_gear;
  int ten_medal; /* once all are beaten: 1 bronze, 2 silver, 3 gold (by the time left) */
  /* yt::CSeq::Exec's cut-in info (GetCutInInfoPt) in the 10-in-a-row: the rival's character
   * (CRivalSetting::GetTenFightCharIndex, -1 none), CTenSeq::SwCutIn (its entrance line on)
   * and the beaten one's (play state 9 Defeat, or 8 Goal past 0.1 s) */
  int cut_char, cut_start, cut_lose;
  /* yt::CSeq::GetInfoTenRivalLine: the road-edge points (display units) of the blue line at
   * the rival, on while play state 2 (clStageEffectManager::update's SetVisible) */
  int ten_line_on;
  float ten_line[2][3];
  int vs_place;   /* a versus (car_set_versus) once over: the place, 1 first (0 still racing) */
  /* a versus while racing (yt::CSeq::Get2DInfoBattle, clWorkSpace +0x340 / +0x344): the link's
   * cars ahead of the player (0 first) and m each link rival i (car_set_versus's others) is
   * behind (negative: ahead), vs_on[i] whether it is in */
  int vs_rank;
  float vs_gap[CAR_RIVALS];
  unsigned char vs_on[CAR_RIVALS];
  int play_state; /* clWorkSpace::getPlayState (CState: 1 Start, 2 Run, ... 9 a ten rival beaten) */
  /* once over (play state 3, 6, 8 or 10): the run's log for the titles (yt::CTitle, CSeq::GetPlayLog) */
  int title_log_on;
  unsigned char title_log[CAR_TITLE_LOG];
  int remain_valid; /* S2DInfoRace distance was finite, nonnegative and available */
  int ten_gap_valid; /* current rival line was observed */
  unsigned char vs_fresh[CAR_RIVALS]; /* active on-road rival and fresh confirmed packet */
  int vs_pcb[CAR_RIVALS];
  double vs_observed[CAR_RIVALS]; /* packet timestamp of this physics snapshot */
} car_race;
/* Clears only the snapshot, for a race teardown or disconnect; no engine writes. */
void car_clear_junction(car_race *r);

/* CInfoSEMc one-shot requests accumulated until snd_update consumes them. */
typedef struct {
  int valb, backfire;
  float valb_vol, backfire_vol, backfire_hz;
  int road_hz; /* pending CInfoSEMc road-strip / road-joint one-shot */
  float road_vol;
  /* Latest physics snapshot: +0x1d is capability, +0x84 its envelope. */
  int rev_enabled;
  unsigned rev_sequence;
  float rev_vol;
} car_se;

typedef struct {
  float rpm, gain;
  unsigned char accel, shift_up, shift_down;
} car_engine_se;

typedef struct {
  car_se se;
  float body[16];   /* model matrix from the arcade (GL column-major, translation in 12..14) */
  float pos[3];
  float yaw, pitch, roll; /* derived from body; yaw 0 faces +z */
  float speed;      /* m/s along the heading (negative = reverse) */
  float steer;      /* smoothed steering input */
  float rpm;
  float rev_rate;   /* rpm over the rev limit, 0..1 (CEngine::GetRevRate) */
  int rev_lamp_frame; /* observed CSeq::nCnt, read-only visual phase */
  float boost;      /* the turbo's boost (CTurbo +4) */
  int gear;         /* 1..5 as the arcade gearbox reports it, 0 = neutral */
  int manual;       /* 0 = automatic (the arcade's AT setting), 1 = manual */
  int on_ground;
  float wall_hit;   /* >0 for a short time after scraping a wall (for effects) */
  /* sound/effect cues; the consumer clears them */
  float slip;       /* 0..1 tyre squeal amount */
  float impact;     /* m/s of the hardest wall hit since last cleared */
  /* car_hits' cues: the last frame's velocity (m/s, world; vel_ok once there is one) and
   * the frames till the arcade's scrape (effect.spark) starting again is a hit */
  float vel[3];
  int vel_ok, sparked;
  int shift_event;  /* +1 up / -1 down since last cleared */
  /* the arcade's camera for this frame (CMachine::GetInfoCarCamera) */
  float cam_view[16]; /* world -> camera, GL column-major */
  float cam_pos[3];
  float cam_fov;      /* horizontal field of view, radians (the arcade's screen is 4:3) */
  float cam_near;
  float cam_blur;     /* the radial blur's strength (clGraphicFrame::setBlur clamps it to 0..1) */
  int mirror;         /* the back mirror's camera below is this frame's (the roof view only) */
  float mirror_view[16], mirror_fov, mirror_near; /* as cam_view, cam_fov (horizontal), cam_near */
  int jct_block[2];   /* junction blocks to show (ids for car_jct_block_name, 0 = none) */
  int n_traffic;      /* the traffic cars on the road this frame */
  car_traffic traffic[CAR_TRAFFIC];
  /* the rivals (car_set_rivals), each: on the road near enough to draw, and its model matrix
   * like body (CSeq::GetInfoRivalCarDisp) */
  int rival_shown[CAR_RIVALS];
  float rival_body[CAR_RIVALS][16];
  /* the tyres (SInfoCarDisp, as nsCarDispManager::clCarDisp::update takes them), per corner
   * CAR_FL, CAR_FR, CAR_RL, CAR_RR: the posture relative to the body (GL column-major; its
   * translation's y is the hub's height, x and z the car's TireLocation) and the turn about
   * the axle (radians) */
  float tyre[4][16], tyre_rot[4];
  float rival_tyre[CAR_RIVALS][4][16], rival_tyre_rot[CAR_RIVALS][4];
#ifdef __ANDROID__
  /* clCarEffectManager's original tire-track inputs, in its native index order:
   * world matrices SInfoCarDisp +0x44..+0x104 and opacities
   * SInfoCarEffect +0x40..+0x4c. Read only; never feed them back to physics. */
  float track_matrix[4][16], track_alpha[4];
#endif
  /* braking, as SInfoCarDisp +0x144 has it for clCarLampManager (its brake lamps' STOP):
   * CMachine::GetInfoCarDisp the brake pedal past 0.2, CRivalCar's slowing down */
  unsigned char brake, rival_brake[CAR_RIVALS];
  /* the headlights' pool on the road (clCarSpotLight, visible while SInfoCarDisp +0x146 is 1:
   * CMachine's !(+0x3b5), the rivals and the movies' cars always) */
  unsigned char spot, rival_spot[CAR_RIVALS];
  car_effect effect, rival_effect[CAR_RIVALS];
  car_race race;
  /* Read-only own-car RollUp inputs from the existing SInfoCarEffect snapshot.
   * Appended to preserve all preceding host wrapper field offsets. Never sent
   * back into the native machine or consumed from the native RNG. */
  TireSmokeInput tire_smoke;
  uint64_t tire_smoke_tick;
  int tire_smoke_valid;
  car_engine_se engine_se; /* sampled with se.rev_sequence */
} car_state;

/* the corners: +x is the car's left */
enum { CAR_FL, CAR_FR, CAR_RL, CAR_RR };

/* The arcade's play views (EPlayView): 1 is the default view behind the car,
 * 0 the view from the car's roof. */
enum { CAR_VIEW_ROOF = 0, CAR_VIEW_BEHIND = 1 };

/* The course cards of the arcade's course select (menu_layout_ta_course), in their order:
 * C1 in, C1 out, New Belt Line CCW/CW, Wangan, Yokohane (K1), Nagoya, Osaka, Fukuoka,
 * Hakone, Tokyo and Kanagawa (the long runs); car_course_id gives the arcade's course id. */
#define CAR_COURSES 12
int car_course_id(int course);
/* the course's time attack slot (clEffTaCourseType, its stage - 363; src/title.h), -1 none */
int car_course_ta_slot(int course);
/* The arcade's cities (a map each, scene files data/<city>/<time zone>/<..>.lua); the
 * Kanagawa and Yokohane roads are on Tokyo's. */
enum { CAR_TOKYO, CAR_OSAKA, CAR_HAKONE, CAR_NAGOYA, CAR_FUKUOKA, CAR_CITIES };
/* the city of a road (EAreaId) */
int car_area_city(int area);
/* the city of a time attack course (a story race's: src/storycity.h) */
int car_course_city(int course);

/* Check that the arcade memory image (phys.img) is in data_dir. Returns 0 on success;
 * on failure writes a message to err. */
int car_init(const char *data_dir, char *err, int err_len);
/* The car to drive: the arcade's ECarType, its number of gears, and the STireDimension
 * its display model gives the physics (front x, radius, z, rear x, radius, z in mm, then
 * the wheel's spokes); src/cardb.h has them for every car of the car select. Then its
 * tune, the card's clCarStyle power and handling (0..24 each, 0 and 0 = stock; the
 * physics caps their sum at CAR_TUNE_TOTAL). */
#define CAR_TUNE_MAX 24
#define CAR_TUNE_TOTAL 34
typedef struct {
  unsigned type;
  int gears;
  float tyres[6];
  int spokes;
  int power, handling;
} car_spec;
extern const car_spec CAR_SPEC_FD3S;

/* Game/engine thread only, like the surrounding global RC/car API.
 * Independent original CTarget Ghost session; never a live VS PCB or an AI
 * fallback. The app owns UI/cloud authority and must keep this result separate
 * from story, TA records and VS stars. Native fields below are a reviewed local
 * ABI binding, NOT a wire format accepted directly from the server. */
enum { CAR_GHOST_CHALLENGE = 1, CAR_GHOST_QUALIFICATION = 2, CAR_GHOST_DEFAULT = 3 };
enum { CAR_GHOST_OFF, CAR_GHOST_PREPARED, CAR_GHOST_RUNNING, CAR_GHOST_FINISHED, CAR_GHOST_FAILED };
#define CAR_GHOST_ABI_VERSION 1u

typedef struct {
  uint32_t abi_version;
  uint64_t session_token; /* nonzero, caller's immutable challenge/qualification binding */
  int kind;
  car_spec rival; /* challenge only: authentic record owner's car/tune/tyres */
  const void *trail;
  size_t trail_bytes; /* copied by prepare; mandatory for CHALLENGE */
  /* Exact reviewed SConfigRaceField words (stage, native word, area,
   * start-mm float bits, goal-mm float bits, native on word). prepare rejects
   * unsupported bindings; an all-zero/default guessed field never starts TA. */
  uint32_t race_field[6];
  int trail_band[3]; /* original cfg+c0/c4/c8: target power, handling, age-hours */
  unsigned char native_flags[2]; /* cfg+d0/d1: hasCrown, firstTutorial; reviewed local binding */
  /* Recording is independent of loading an opponent: challenge defaults off.
   * Qualification requires record_player=1 and a supported explicit binding. */
  int record_player;
} car_ghost_config;

#define CAR_GHOST_CROWN_RUNOUT_TICKS 90u

typedef struct {
  int status, kind;
  uint64_t session_token;
  int native_target_valid; /* verified non-null Target+valid sampler; never generic rival fallback */
  int display_valid, result_valid;
  int place, goal_reached, won; /* zero-based finish order; valid only with result_valid */
  float gap_m; /* signed advantage in meters; local Crown freezes it at first crossing */
  float live_gap_mm; /* current Get2DInfoTarget advantage, NAN when no sample was read */
  uint32_t collision_registrations, native_ticks, finish_tick;
  int recording, export_ready;
  int native_default_ai_valid; /* ONLY explicit compiled-default kind3; NOT a sampler or fallback */
} car_ghost_observation;

/* 1 accepted, 0 fail-closed. Configuration is for the next car_start only;
 * a rejected Ghost session may not silently start one of the original modes.
 * call clear before returning to a normal four-mode race. */
/* ERamp is the original enum 1..22, not the menu's zero-based index.
 * Only route==0 (native fraction 0) is enabled in this reviewed ABI; every
 * other route fails closed. Requires car_init; obtains all six words from the
 * original helper and never synthesizes an arbitrary TA race field. */
int car_ghost_race_field(int ramp, int route, int tutorial, uint32_t output[6]);
/* Reviewed native source/ELF/patch-ABI + floating-point cohort, 64 lowercase hex.
 * NULL for an old/unsupported physics translation. This is not cloud authority. */
const char *car_ghost_physics_id(void);
/* Coarse scene/resource selection ONLY. Returns a compatible existing course
 * index for this native field's city, or -1. Never substitutes a TA race field. */
int car_ghost_render_course(const uint32_t race_field[6]);
int car_ghost_prepare(const car_ghost_config *config);

/* Separately approved LOCAL shipped-record binding. Never pass server fields
 * directly here or promote its result to a cloud crown/qualification. The caller
 * retains the full immutable cosmetics/profile and supplies their model/tune
 * fields here; player car/style is still supplied separately to car_start.
 * Header stage is mandatory, and must agree with raw-ramp/route ORIGINAL helper.
 * bind needs car_init (loads phys.img on demand), not a renderer/GPU scene. */
typedef struct {
  uint32_t raw_model_id; /* emCarModelID (color), NOT ECarType */
  int power, handling;
  uint32_t dress, dress_x, player_win_count; /* serialized profile; not difficulty comment/class */
  int raw_ramp, raw_route; /* frontend table index 0..21 and original route number */
  uint32_t header_stage;
  uint64_t source_id, session_token; /* local frozen catalogue/selection provenance, not authentication */
  const void *trail;
  size_t trail_bytes;
  int has_crown, first_tutorial, age_hours; /* native gameplay flags, NOT cloud authority */
  uint32_t raw_custom_color, raw_aero, raw_wheel; /* original palette/body/emTireModelID; stock wheel143 */
} car_ghost_arcade_spec;
typedef struct {
  car_spec rival;
  uint32_t race_field[6];
  int maker, car, color, pack, paint, render_course, city, route_count;
  int target_level, target_rank; /* original zero-based native indices */
  uint64_t source_id;
  int raw_ramp, raw_route, first_tutorial; /* exact native policy revalidation */
  int ramp; /* actual ERamp from frontend table +8; raw_ramp+1 is NOT equivalent */
  int base_paint, custom_color;
  /* paint is desired PACKED palette: base palettes followed by original custom
   * palettes. Nonzero custom_color requires separately approved palette assets;
   * renderer readiness MUST verify/load that paint, NEVER silently use base. */
} car_ghost_arcade_binding;
int car_ghost_arcade_bind(const car_ghost_arcade_spec *spec, car_ghost_arcade_binding *binding);
/* Fills an actual native StageAry/pAreaAry policy, including full ordered road
 * sequence validation. Single engine thread; use immediately. Context expires
 * on the next policy call or car_ghost_clear; prepare independently rechecks. */
int car_ghost_arcade_policy(const car_ghost_arcade_binding *binding, ghost_format_policy *policy);
int car_ghost_arcade_validate_trail(const car_ghost_arcade_binding *binding, const void *trail, size_t bytes);
/* Always non-recording original CTarget mode8. Copies bytes before returning.
 * Rejection clears stale readiness, and cannot fall into TA/AI/ordinary VS. */
int car_ghost_arcade_prepare(const car_ghost_arcade_spec *spec, car_ghost_arcade_binding *binding);
int car_ghost_arcade_info(car_ghost_arcade_binding *binding);
/* Marks a prepared mode-8 local Crown challenge. When requested, the existing
 * native sampler records the run, including its post-goal automatic drive. */
int car_ghost_arm_local_crown(uint64_t session_token, int record_player);
/* Player-generated non-crown trails may also stop right at the goal. */
int car_ghost_arm_rival_runout(uint64_t session_token);
int car_ghost_arm_cloud_recording(uint64_t session_token);
int car_ghost_crown_area_matches(unsigned area,int raw_ramp);
/* A finished Time Attack can be replayed as a regular Ghost on its exact
 * native field. The profile's reserved raw-ramp key is this base plus course. */
#define CAR_GHOST_TA_RAMP_BASE CAR_LINK_RAMPS
int car_ghost_time_attack_area(int course);
/* Optional capture for the next ordinary Time Attack only. Does not change
 * race mode or scoring, and fails without affecting the live race. */
int car_ghost_arm_time_attack_recording(uint64_t session_token);
int car_ghost_time_attack_recording_info(uint64_t session_token, int *course,
                                         uint32_t field[6], car_spec *owner);
int car_ghost_time_attack_recording_export(uint64_t session_token, void *output,
                                           size_t capacity, size_t *bytes);
/* Original clCarStyle normal serialized tune path + 0x932a280 table and win
 * promotions. Transient native override flag/alternate tune is NOT serialized
 * by TargetDataReader and is not inferred from dress or dress_x. */
int car_ghost_arcade_difficulty(int power, int handling, uint32_t wins, int *level, int *rank);
/* Compiled clTargetDefault metadata is a DISTINCT original mode8 target-AI
 * source, NEVER a fallback for an absent/corrupt recorded trail. Enumeration
 * consumes no RNG and leaves car.{raw_ramp,ramp,raw_route,city,render_course}=-1.
 * 120 source rows; original manager skips eleven nonzero GUEST placeholders. */
#define CAR_GHOST_DEFAULT_RECORDS 120u
#define CAR_GHOST_DEFAULT_SOURCE_BASE UINT64_C(0x8000000000000000)
typedef struct {
  uint32_t index, manager_eligible, id_devel, id1, id2, name[5];
  uint32_t raw_model_id, raw_custom_color, raw_vinyl, raw_bonnet, raw_wing,
           raw_aero, raw_mirror, raw_wheel, raw_neon, dress, dress_x;
  uint32_t player_win_count, title, class_id, odo_count, cool_wild, smooth_rough;
  int crown_area; /* 0..7 only that source area; 8 means no crown; local gameplay only */
  car_ghost_arcade_binding car; /* source-owned profile/model/tune; no chosen course yet */
} car_ghost_default_view;
typedef struct {
  uint32_t index, area;
  uint64_t session_token;
  int first_tutorial;
} car_ghost_default_spec;
typedef struct {
  car_ghost_default_view record;
  car_ghost_arcade_binding car; /* original random ramp/route and field frozen ONCE */
  uint32_t area;
  uint64_t session_token, choice_cookie; /* native monotonic choice; never recycled by clear */
} car_ghost_default_binding;
int car_ghost_default_available(void); /* zero on v6/old engine; metadata may still enumerate */
int car_ghost_default_record(uint32_t index, car_ghost_default_view *view);
/* Call ONLY for actual user confirmation, not directory/render enumeration.
 * Original getRandomRamp/getRandomRoute consume original MT RNG once; preparing
 * and info NEVER reroll. New choice / clear invalidates a previous binding. */
int car_ghost_default_select(const car_ghost_default_spec *spec, car_ghost_default_binding *binding);
int car_ghost_default_prepare(const car_ghost_default_binding *binding);
int car_ghost_default_info(car_ghost_default_binding *binding);
void car_ghost_clear(void);
/* Nonzero means a Ghost request exists (including FAILED), not GhostReady.
 * Inspect status/kind/native_target_valid/result_valid separately. */
int car_ghost_status(car_ghost_observation *observation);
/* End recording through the original native Save, then read back validated
 * payload bytes. NULL output queries size; no pointers/heap objects are exported.
 * Call while the exact Ghost race still owns the native image, before car_start.
 * If finish lands between the original step-3 samples, export_ready stays false;
 * keep the normal fixed-step engine ticking through its post-goal frames and
 * retry (do not synthesize/duplicate a final sample or change frozen rank). */
int car_ghost_export(void *output, size_t capacity, size_t *bytes);
/* GetHorsePower (0x8568a44): the horsepower at a power tune, the car's stock figure
 * (src/cardb.h, GetCarData +0x20) at power 0. */
int car_tune_hp(int stock_hp, int power);
/* GetHandling (0x8568a74): the balance grade of a tune by handling - power: 0 DG (-8 and
 * below), 1 D (-7..-4), 2 B (-3..3), 3 G (4..7), 4 HG (8 and up). */
enum { CAR_GRADE_DG, CAR_GRADE_D, CAR_GRADE_B, CAR_GRADE_G, CAR_GRADE_HG };
int car_tune_grade(int power, int handling);

/* A CPU rival (yt::CRivalAI driving a yt::CRivalCar, as in the story mode): its ECarType,
 * its STireDimension like car_spec's, the ECharacter whose driving it has, the story's loop
 * (clWorkSpace's lap: GetStoryRivalFeature takes the first loop's character settings at 0,
 * the second's past it), the episode's losses so far (GetSettingPt eases the rubber band by
 * them, up to 3) and the race (ESeries: the start, the distance and the rival's character in
 * data/carconfig/ytConfigStory.txt). */
typedef struct {
  unsigned type;
  float tyres[6];
  int spokes;
  int character, level, losses, series;
} car_rival;
/* The next car_start races `n` rivals (up to CAR_RIVALS; 0: a time attack alone). The race
 * is the story mode's (EGameMode 4) with the first one's select and race. */
void car_set_rivals(const car_rival *rivals, int n);
/* Enable the arcade's optional time-attack traffic; other modes are unaffected. */
void car_set_ta_traffic(int on);

/* In-memory-only story transition. The caller binds a nonzero token to one
 * exact uninterrupted transition and supplies the current/next ESeries.
 * Capture returns -1 if End was not entered, 0 if End ran without a usable
 * snapshot, and 1 if End ran and captured. Once End runs the old car is no
 * longer ready, even on failure. Arm permits repeated matching car_start calls
 * for movie initialization; it does not consume the snapshot. loaded reports
 * whether the most recent car_start actually accepted it. Finalize consumes a
 * matching snapshot only after a successful load; cancel always clears it. */
int car_story_carry_capture(uint64_t token, int expected_series);
int car_story_carry_arm(uint64_t token, int target_series);
int car_story_carry_loaded(uint64_t token);
int car_story_carry_finalize(uint64_t token);
void car_story_carry_cancel(void);
/* The next car_start is a 10-in-a-row race (SConfigPlay mode 7) on the EStage (333..342; 0 off)
 * at the level (0..9, 10 the extend), with its rivals in order (their tyres for CSeq::Exec, which
 * brings each on as the one before is beaten). */
#define CAR_TEN_RIVALS 32
void car_set_ten(int stage, int level, const car_rival *rivals, int n);
static inline void car_set_rival(const car_rival *rival) { car_set_rivals(rival, rival != 0); }

/* A versus race (EGameMode 5, Battle: clRaceThread::initJoin) against other machines over the
 * cabinet link, the arcade's yt::CLinx: each machine drives its own car and its share of the
 * traffic and sends the frame's race packet (SLxPacket, CAR_LINK_PACKET bytes) to the others,
 * whose cars it shows from theirs (yt::CLxRival). This machine is PCB `pcb` (0..3); the others
 * each have theirs, their car (type, tyres) and tune. The race starts at the join ramp `ramp`
 * (0..CAR_LINK_RAMPS-1, the arcade's table at 0x9739140) and runs `km` to the goal; `seed` is
 * the race's shared random number (clNet::getJoinRaceRandom). The transport: link_send gets each
 * frame's packet, link_receive (each frame, before the packets are read) hands the newest from
 * each machine to car_link_deliver. For the next car_start only. */
#define CAR_LINK_PACKET 0x278
#define CAR_LINK_MACHINES 4
#define CAR_LINK_RAMPS 22
typedef struct {
  int pcb;
  unsigned type;
  float tyres[6];
  int spokes;
  int power, handling;
} car_link_car;
typedef struct {
  void (*send)(const unsigned char *packet, int len, void *ctx);
  void (*receive)(void *ctx);
  void *ctx;
} car_link_io;
void car_set_versus(int pcb, const car_link_car *others, int n, int ramp, float km, unsigned seed, const car_link_io *io);
void car_link_deliver(int pcb, const unsigned char *packet, int len);
/* Transport calls active=1 only after delivering a NEW packet validated for
 * room, race, PCB and sequence; never on cached replay. active=0 on disconnect/teardown.
 * No notification means unknown. Freshness expires after one monotonic second. */
void car_link_fresh(int pcb, int active);
int car_link_time_fresh(double now, double received);
int car_link_observation_fresh(int pcb, double observed);
/* the join ramp's name (C1_IN_KANDABASHI ...) */
const char *car_link_ramp_name(int ramp);

/* Set up a time attack on `course` in `spec` (NULL: the FD3S), with the traffic on,
 * with an automatic or manual gearbox (manual shifts with car_input.shift_up/down) and
 * put the car on its start line, rolling like the arcade's time attack start. The arcade
 * keeps the time: its limit, the checkpoints' extensions and the goal (car_state.race).
 * Returns 0 on success. */

/* Read-only last-completed native TA step; game-thread only. No simulation/RNG calls.
 * Separate positive APP TA/attempt/identity/official/reset/abort gates remain mandatory.
 * Native state 0/1/2/7/8 can be sampled; only goal==1 is a terminal Goal.
 * Up to 8 scored sections plus their native start-zero checkpoint (9 entries).
 * Only split_bits[0..split_count-1] are copied native passed checkpoints; the
 * zeroed unused tail is not a measured/manufactured split. No raw model ID is inferred.
 * Bind the immutable process cohort separately with car_ghost_physics_id(). */
#define CAR_TA_RANKING_ABI_VERSION 1u
typedef struct {
  uint32_t abi_version, native_mode, native_state, goal;
  int course, course_id, ta_slot, city, traffic, manual;
  car_spec owner;
  uint32_t race_field[6];
  uint32_t elapsed_bits, countdown_bits, time_left_bits;
  uint32_t checkpoint_count, checkpoint_next, split_count;
  uint32_t split_bits[CAR_SECTIONS + 1];
} car_ta_ranking_observation;
/* Returns 0 and zeroes output for unavailable/stale/non-TA/timeout/corrupt state.
 * Does not load an image, refresh the world, consume a result, or grant ranking authority. */
int car_ta_ranking_info(car_ta_ranking_observation *out);

int car_start(car_state *c, int course, int manual, const car_spec *spec);
/* Switch between the automatic and manual gearbox on the move. */
/* Put the car back on the road where it is, facing the course in the start's lane (the
 * reset key; the race and its time go on). */
void car_reset(car_state *c);
/* The hits' sound cues (impact, wall_hit) from the whole change of velocity, a bounce
 * sideways off a wall or a car as much as a loss of speed, and from the arcade's own scrape
 * (SInfoCarEffect) starting; off: from a sudden loss of speed alone, as on the iPad. */
void car_hits(int on);
/* Name of a junction block: the scene group of its arrow boards (coursearrow igb files), or NULL. */
#define CAR_JCT_BLOCKS 69 /* ids 1..68 */
const char *car_jct_block_name(int id);
/* youTitle::GetTitleList on a _TitleData_ (data, n bytes; src/title.c fills it as
 * clWorkSpace::judgeTitle does): the titles it gives (out, 0 for an empty slot), how many */
int car_title_list(const unsigned char *data, int n, int out[3]);
/* Which view the camera follows from the next frame on. */
void car_view(int view);
/* One arcade frame (1/60 s). */
void car_update(car_state *c, const car_input *in);
float car_kmh(const car_state *c);
unsigned car_vs_drive_style(unsigned previous);

/* The story's realtime movies (data/rtmovie, the arcade's YOURTMOVIE_CPP::clMovieSystem): the
 * movie (clEffStoryType's RtMovie id, MovieTableData.txt's row), the player's car (NULL: the
 * FD3S) and the rivals (up to CAR_RIVALS; their type and tyres). Returns the movie's length in frames (0: it failed). Then per arcade frame,
 * frame 0, 1, ... up to that length: the cars (body: car 0, rival_*: cars 1..3) and the movie's
 * camera into c; returns the cars shown (bit k: car k). car_movie_end before the next car_start. */
float car_movie_start(car_state *c, int movie, const car_spec *player, const car_rival *rivals, int n);
int car_movie_update(car_state *c, float frame);
void car_movie_end(void);

#endif
